            Choose all answers that apply for each question.
          </p>
        </header>
      `;
    }

    function QuizCard({ questions }) {
      return `
        <section class="quiz-card" aria-labelledby="quiz-title">
          <div class="quiz-header">
            <div>
              <h2 id="quiz-title">Language fundamentals</h2>
              <p>Each question can have more than one correct answer.</p>
            </div>
            <div class="progress-pill">${questions.length} questions</div>
          </div>
          <form id="quiz-form">
