            <div class="actions">
              <p class="result" id="result" aria-live="polite"></p>
              <button type="submit">Submit answers</button>
            </div>
          </form>
        </section>
      `;
    }

    function QuestionField(question, index) {
      return `
        <div class="form-field">
          <h3 class="question-title">${index + 1}. ${question.title}</h3>
          ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
